def main(path):
    with open(path, encoding="utf-8") as f:
        data = json.load(f)

    by_region = {code: {} for code, _ in REGIONS}

    for c in data.values():
        # Accept Saudi Arabia and Iraq
        if c["countrycode"] not in ("SA", "IQ"):
            continue

        gid = c["geonameid"]

        if gid in NAMES and NAMES[gid] is None:
            continue

        name = NAMES.get(gid) or next(
            (
                n for n in reversed(c.get("alternatenames", []))
                if all("\u0600" <= ch <= "\u06ff" or ch == " " for ch in n)
            ),
            None,
        )

        region = REGION_FIX.get(gid, c["admin1code"])

        if not name or region not in by_region:
            continue

        by_region[region].setdefault(
            name,
            (
                POPULATION_FIX.get(gid, c["population"]),
                c["latitude"],
                c["longitude"],
            ),
        )

    for region, name, lat, lon in EXTRA:
        by_region[region].setdefault(name, (0, lat, lon))

    rows = []

    for code, rname in REGIONS:
        cities = sorted(
            by_region[code].items(),
            key=lambda kv: -kv[1][0],
        )

        items = ",\n".join(
            f'            {{"{n}", "{lat:.4f}", "{lon:.4f}"}}'
            for n, (_, lat, lon) in cities
        )

        rows.append(
            f'        new Region("{rname}", new String[][] {{\n'
            f'{items}\n'
            f'        }})'
        )

    body = ",\n".join(rows)

    out = (
        Path(__file__).resolve().parents[2]
        / "android/app/src/main/java/sa/urtv/screensaver/Cities.java"
    )

    out.write_text(
        f"""package sa.urtv.screensaver;

/** Generated by .github/tools/gen_cities.py from GeoNames — do not edit by hand. */
final class Cities {{
    static final class Region {{
        final String name;
        final String[][] cities;   // name, latitude, longitude
        Region(String name, String[][] cities) {{
            this.name = name;
            this.cities = cities;
        }}
    }}

    static final Region[] REGIONS = {{
{body}
    }};

    private Cities() {{}}
}}
""",
        encoding="utf-8",
    )

    print(
        f"{sum(len(v) for v in by_region.values())} cities "
        f"in {len(REGIONS)} regions -> {out.name}"
    )


if __name__ == "__main__":
    main(sys.argv[1])
